import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

const SCHEMA = `
CREATE TABLE IF NOT EXISTS jobs (
  seq INTEGER PRIMARY KEY AUTOINCREMENT,
  id TEXT NOT NULL UNIQUE,
  status TEXT NOT NULL,
  input TEXT NOT NULL,
  steps INTEGER NOT NULL,
  fail_attempts INTEGER NOT NULL,
  attempts INTEGER NOT NULL DEFAULT 0,
  progress_completed INTEGER NOT NULL DEFAULT 0,
  result_output TEXT,
  error TEXT,
  run_after INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS jobs_status_seq ON jobs (status, seq);
CREATE TABLE IF NOT EXISTS idempotency_keys (
  key TEXT PRIMARY KEY,
  job_id TEXT NOT NULL REFERENCES jobs (id),
  input TEXT NOT NULL,
  steps INTEGER NOT NULL,
  fail_attempts INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS meta (
  key TEXT PRIMARY KEY,
  value INTEGER NOT NULL
);
`;

/** Runs \`fn\` inside a write transaction. BEGIN IMMEDIATE takes the write lock up front, so
 * the server and worker never interleave a read-check-write sequence. */
export function transaction<T>(db: DatabaseSync, fn: () => T): T {
  db.exec('BEGIN IMMEDIATE');
  let result: T;
  try {
    result = fn();
    db.exec('COMMIT');
  } catch (e) {
    try {
      db.exec('ROLLBACK');
    } catch {
      // the transaction was already rolled back by SQLite
    }
    throw e;
  }
  return result;
}

/** Opens the SQLite database shared by the server and worker processes and ensures the schema exists. */
export function openDatabase(path: string = process.env.DATABASE_PATH || 'data/jobs.db'): DatabaseSync {
  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  // busy_timeout first: switching to WAL takes a brief exclusive lock, and the server and worker
  // open the same database at once, so the loser must wait rather than fail.
  db.exec('PRAGMA busy_timeout = 5000; PRAGMA journal_mode = WAL; PRAGMA synchronous = NORMAL;');
  transaction(db, () => db.exec(SCHEMA));
  return db;
}
import { randomUUID } from 'node:crypto';
import type { DatabaseSync, SQLInputValue } from 'node:sqlite';
import { transaction } from './db.ts';

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

export interface NewJob {
  input: string;
  steps: number;
  failAttempts: number;
}

/** A job as returned by the API. */
export interface Job {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

/** A row of the `jobs` table, as stored. */
export interface JobRow {
  seq: number;
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  progress_completed: number;
  result_output: string | null;
  error: string | null;
  run_after: number;
  created_at: string;
  updated_at: string;
}

interface IdempotencyRow {
  job_id: string;
  input: string;
  steps: number;
  fail_attempts: number;
}

export const HEARTBEAT_KEY = 'worker_heartbeat';
/** The worker counts as up if its heartbeat is no older than this. */
export const WORKER_STALE_MS = 3_000;

/** Returns a single row, or undefined. */
function one<T>(db: DatabaseSync, sql: string, ...params: SQLInputValue[]): T | undefined {
  return db.prepare(sql).get(...params) as unknown as T | undefined;
}

function run(db: DatabaseSync, sql: string, ...params: SQLInputValue[]): void {
  db.prepare(sql).run(...params);
}

function getRow(db: DatabaseSync, id: string): JobRow {
  const row = one<JobRow>(db, 'SELECT * FROM jobs WHERE id = ?', id);
  if (!row) throw new Error(`job ${id} disappeared`);
  return row;
}

export function toJob(row: JobRow): Job {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.progress_completed, total: row.steps },
    result: row.status === 'completed' && row.result_output !== null ? { output: row.result_output } : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

export type CreateOutcome = { job: Job; created: boolean } | 'conflict';

/** Creates a job. With an idempotency key, an earlier job with the same key is returned instead,
 * or 'conflict' is returned when the payload differs. The lookup and insert share one transaction. */
export function createJob(db: DatabaseSync, payload: NewJob, key?: string): CreateOutcome {
  return transaction(db, (): CreateOutcome => {
    if (key !== undefined) {
      const existing = one<IdempotencyRow>(
        db,
        'SELECT job_id, input, steps, fail_attempts FROM idempotency_keys WHERE key = ?',
        key,
      );
      if (existing) {
        if (existing.input !== payload.input || existing.steps !== payload.steps || existing.fail_attempts !== payload.failAttempts) {
          return 'conflict';
        }
        return { job: toJob(getRow(db, existing.job_id)), created: false };
      }
    }
    const id = randomUUID();
    const now = new Date().toISOString();
    run(
      db,
      `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress_completed, run_after, created_at, updated_at)
       VALUES (?, 'queued', ?, ?, ?, 0, 0, 0, ?, ?)`,
      id,
      payload.input,
      payload.steps,
      payload.failAttempts,
      now,
      now,
    );
    if (key !== undefined) {
      run(
        db,
        'INSERT INTO idempotency_keys (key, job_id, input, steps, fail_attempts) VALUES (?, ?, ?, ?, ?)',
        key,
        id,
        payload.input,
        payload.steps,
        payload.failAttempts,
      );
    }
    return { job: toJob(getRow(db, id)), created: true };
  });
}

export function findJob(db: DatabaseSync, id: string): Job | undefined {
  const row = one<JobRow>(db, 'SELECT * FROM jobs WHERE id = ?', id);
  return row ? toJob(row) : undefined;
}

/** All jobs, newest first. */
export function listJobs(db: DatabaseSync): Job[] {
  return db.prepare('SELECT * FROM jobs ORDER BY seq DESC').all().map((r) => toJob(r as unknown as JobRow));
}

// ---- Worker operations ----

/** Writes the worker heartbeat. A value of 0 means the worker has stopped. */
export function writeHeartbeat(db: DatabaseSync, now: number): void {
  run(db, 'INSERT INTO meta (key, value) VALUES (?, ?) ON CONFLICT (key) DO UPDATE SET value = excluded.value', HEARTBEAT_KEY, now);
}

export function isWorkerUp(db: DatabaseSync, now: number): boolean {
  const row = one<{ value: number }>(db, 'SELECT value FROM meta WHERE key = ?', HEARTBEAT_KEY);
  return row !== undefined && row.value > 0 && now - row.value <= WORKER_STALE_MS;
}

/** Puts jobs that were `running` back in the queue. Only a worker that is not running can see them,
 * so this is safe at worker startup when a single worker is in use. */
export function requeueOrphanedJobs(db: DatabaseSync, now: number): number {
  return Number(
    db
      .prepare(
        "UPDATE jobs SET status = 'queued', progress_completed = 0, run_after = 0, updated_at = ? WHERE status = 'running'",
      )
      .run(new Date(now).toISOString()).changes,
  );
}

/** Takes the oldest queued job that is due, and starts an attempt on it. */
export function claimNextJob(db: DatabaseSync, now: number): JobRow | undefined {
  return transaction(db, () => {
    const row = one<JobRow>(
      db,
      "SELECT * FROM jobs WHERE status = 'queued' AND run_after <= ? ORDER BY seq LIMIT 1",
      now,
    );
    if (!row) return undefined;
    run(
      db,
      "UPDATE jobs SET status = 'running', attempts = attempts + 1, progress_completed = 0, updated_at = ? WHERE id = ?",
      new Date(now).toISOString(),
      row.id,
    );
    return getRow(db, row.id);
  });
}

export function recordProgress(db: DatabaseSync, id: string, completed: number, now: number): void {
  run(db, 'UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE id = ?', completed, new Date(now).toISOString(), id);
}

export function completeJob(db: DatabaseSync, id: string, output: string, now: number): void {
  run(
    db,
    "UPDATE jobs SET status = 'completed', progress_completed = steps, result_output = ?, error = NULL, updated_at = ? WHERE id = ?",
    output,
    new Date(now).toISOString(),
    id,
  );
}

export function failJob(db: DatabaseSync, id: string, error: string, now: number): void {
  run(
    db,
    "UPDATE jobs SET status = 'failed', progress_completed = 0, result_output = NULL, error = ?, updated_at = ? WHERE id = ?",
    error,
    new Date(now).toISOString(),
    id,
  );
}

/** Returns a job to the queue. It is not picked up again before `runAfter` (epoch ms). */
export function requeueJob(db: DatabaseSync, id: string, runAfter: number, now: number): void {
  run(
    db,
    "UPDATE jobs SET status = 'queued', progress_completed = 0, run_after = ?, updated_at = ? WHERE id = ?",
    runAfter,
    new Date(now).toISOString(),
    id,
  );
}
import type { NewJob } from './jobs.ts';

export interface FieldError {
  field: string;
  message: string;
}

export const IDEMPOTENCY_KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;

const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);
export const MAX_INPUT_LENGTH = 1000;

const isPlainObject = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v);

/** Validates a parsed request body and applies defaults. Returns every problem found. */
export function validateNewJob(body: unknown): { payload?: NewJob; errors: FieldError[] } {
  if (!isPlainObject(body)) return { errors: [{ field: 'body', message: 'must be a JSON object' }] };

  const errors: FieldError[] = [];
  for (const key of Object.keys(body)) {
    if (!ALLOWED_FIELDS.has(key)) errors.push({ field: key, message: 'is not a recognised field' });
  }

  let input: string | undefined;
  if (!Object.hasOwn(body, 'input')) {
    errors.push({ field: 'input', message: 'is required' });
  } else if (typeof body.input !== 'string') {
    errors.push({ field: 'input', message: 'must be a string' });
  } else if (body.input.length < 1 || body.input.length > MAX_INPUT_LENGTH) {
    errors.push({ field: 'input', message: `must be 1 to ${MAX_INPUT_LENGTH} characters` });
  } else if (body.input.trim() === '') {
    errors.push({ field: 'input', message: 'must not be only whitespace' });
  } else {
    input = body.input;
  }

  const steps = intField(body, errors, 'steps', 1, 20, 5);
  const failAttempts = intField(body, errors, 'failAttempts', 0, 5, 0);

  if (errors.length > 0 || input === undefined || steps === undefined || failAttempts === undefined) {
    return { errors };
  }
  return { payload: { input, steps, failAttempts }, errors };
}

function intField(body: Record<string, unknown>, errors: FieldError[], name: string, min: number, max: number, dflt: number): number | undefined {
  if (!Object.hasOwn(body, name)) return dflt;
  const v = body[name];
  if (typeof v !== 'number' || !Number.isInteger(v) || v < min || v > max) {
    errors.push({ field: name, message: `must be an integer from ${min} to ${max}` });
    return undefined;
  }
  return v;
}
import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';
import {
  claimNextJob,
  completeJob,
  failJob,
  recordProgress,
  requeueJob,
  requeueOrphanedJobs,
  writeHeartbeat,
  type JobRow,
} from './jobs.ts';

const STEP_MS = 100;
/** Attempt n fails at its first step when n <= failAttempts. A job gets this many attempts in total. */
const MAX_ATTEMPTS = 3;
/** Delay before a failed attempt is retried. Must lie between 250 ms and 2 s. */
const RETRY_DELAY_MS = 500;
const POLL_MS = 200;
const HEARTBEAT_MS = 1_000;

const db = openDatabase();
let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

/** Runs one attempt. Returns 'interrupted' if shutdown was requested part-way through. */
async function runAttempt(job: JobRow): Promise<'done' | 'interrupted'> {
  const attempt = job.attempts;
  if (attempt <= job.fail_attempts) {
    // Simulated transient failure at the first step, before any progress is recorded.
    await sleep(STEP_MS);
    const now = Date.now();
    if (attempt >= MAX_ATTEMPTS) failJob(db, job.id, 'transient failure', now);
    else requeueJob(db, job.id, now + RETRY_DELAY_MS, now);
    return 'done';
  }

  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) return 'interrupted';
    recordProgress(db, job.id, step, Date.now());
  }
  completeJob(db, job.id, job.input.toUpperCase(), Date.now());
  return 'done';
}

/** Keeps the heartbeat fresh so the server can report the worker as up. */
const heartbeat = setInterval(() => {
  try {
    writeHeartbeat(db, Date.now());
  } catch (e) {
    console.error('heartbeat failed:', e);
  }
}, HEARTBEAT_MS);

writeHeartbeat(db, Date.now());
// Jobs left `running` by a worker that died are processed again.
const recovered = requeueOrphanedJobs(db, Date.now());
if (recovered > 0) console.log(`requeued ${recovered} interrupted job(s)`);
console.log('worker started');

while (!stopping) {
  let job: JobRow | undefined;
  try {
    job = claimNextJob(db, Date.now());
  } catch (e) {
    console.error('claim failed:', e);
  }
  if (!job) {
    await sleep(POLL_MS);
    continue;
  }
  try {
    const outcome = await runAttempt(job);
    if (outcome === 'interrupted') requeueJob(db, job.id, 0, Date.now());
  } catch (e) {
    console.error(`attempt on job ${job.id} failed:`, e);
  }
}

clearInterval(heartbeat);
try {
  writeHeartbeat(db, 0);
} finally {
  db.close();
}
console.log('worker stopped');
import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { openDatabase } from './db.ts';
import { createJob, findJob, isWorkerUp, listJobs } from './jobs.ts';
import { IDEMPOTENCY_KEY_RE, validateNewJob, type FieldError } from './validation.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');
const MAX_BODY_BYTES = 64 * 1024;

function sendJson(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...headers });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  sendJson(res, status, { error: { code, message, ...(fields ? { fields } : {}) } });
}

function sendInvalid(res: ServerResponse, errors: FieldError[]): void {
  const summary = errors.map((e) => `${e.field} ${e.message}`).join('; ');
  sendError(res, 400, 'invalid_request', `Invalid request: ${summary}`, errors);
}

function methodNotAllowed(res: ServerResponse, allowed: string[]): void {
  sendJson(
    res,
    405,
    { error: { code: 'method_not_allowed', message: `Method not allowed. Allowed: ${allowed.join(', ')}` } },
    { allow: allowed.join(', ') },
  );
}

function isJsonContentType(value: string | undefined): boolean {
  const mediaType = (value ?? '').split(';')[0]!.trim().toLowerCase();
  return mediaType === 'application/json' || /^application\/[^/]+\+json$/.test(mediaType);
}

/** Reads the whole body as UTF-8. Resolves null if it is larger than MAX_BODY_BYTES. */
function readBody(req: IncomingMessage): Promise<string | null> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size <= MAX_BODY_BYTES) chunks.push(chunk);
    });
    req.on('end', () => resolve(size > MAX_BODY_BYTES ? null : Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

async function handleCreate(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const errors: FieldError[] = [];
  const keyHeader = req.headers['idempotency-key'];
  let key: string | undefined;
  if (keyHeader !== undefined) {
    if (typeof keyHeader === 'string' && IDEMPOTENCY_KEY_RE.test(keyHeader)) key = keyHeader;
    else errors.push({ field: 'Idempotency-Key', message: 'must match ^[A-Za-z0-9_-]{1,128}$' });
  }

  const raw = await readBody(req);
  if (!isJsonContentType(req.headers['content-type'])) {
    errors.push({ field: 'body', message: 'Content-Type must be application/json' });
    return sendInvalid(res, errors);
  }
  if (raw === null) {
    errors.push({ field: 'body', message: `must be at most ${MAX_BODY_BYTES} bytes` });
    return sendInvalid(res, errors);
  }

  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch {
    errors.push({ field: 'body', message: 'is not valid JSON' });
    return sendInvalid(res, errors);
  }

  const result = validateNewJob(parsed);
  errors.push(...result.errors);
  if (errors.length > 0 || !result.payload) return sendInvalid(res, errors);

  const outcome = createJob(db, result.payload, key);
  if (outcome === 'conflict') {
    return sendError(res, 409, 'idempotency_conflict', 'Idempotency-Key was already used with a different payload.');
  }
  sendJson(res, outcome.created ? 201 : 200, outcome.job);
}

function handleRequest(req: IncomingMessage, res: ServerResponse): Promise<void> | void {
  const method = req.method ?? 'GET';
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');

  if (pathname === '/health') {
    if (method !== 'GET') return methodNotAllowed(res, ['GET']);
    const worker = isWorkerUp(db, Date.now()) ? 'up' : 'down';
    return sendJson(res, 200, { status: 'ok', worker });
  }

  if (pathname === '/') {
    if (method !== 'GET') return methodNotAllowed(res, ['GET']);
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }

  if (pathname === '/api/jobs') {
    if (method === 'GET') return sendJson(res, 200, { jobs: listJobs(db) });
    if (method === 'POST') return handleCreate(req, res);
    return methodNotAllowed(res, ['GET', 'POST']);
  }

  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) {
    if (method !== 'GET') return methodNotAllowed(res, ['GET']);
    let id: string;
    try {
      id = decodeURIComponent(match[1]!);
    } catch {
      return sendError(res, 404, 'not_found', 'No such job.');
    }
    const job = findJob(db, id);
    if (!job) return sendError(res, 404, 'not_found', 'No such job.');
    return sendJson(res, 200, job);
  }

  sendError(res, 404, 'not_found', 'No such route.');
}

const server = createServer((req, res) => {
  Promise.resolve()
    .then(() => handleRequest(req, res))
    .catch((e: unknown) => {
      console.error('request failed:', e);
      if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
    });
});

const port = Number(process.env.PORT ?? 3000);
server.listen(port, () => console.log(`server listening on ${port}`));
server.on('error', (e) => {
  console.error('server error:', e);
  process.exit(1);
});

let stopping = false;
function shutdown(): void {
  if (stopping) return;
  stopping = true;
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeIdleConnections();
  // Keep-alive connections that are still busy must not hold the process open indefinitely.
  setTimeout(() => {
    server.closeAllConnections();
  }, 1_000).unref();
}
for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, shutdown);
