      });

      /** Map from job id to its list element, so existing rows are updated rather than replaced. */
      const rows = new Map();

      const makeRow = (id) => {
        const li = document.createElement('li');
        li.setAttribute('data-testid', 'job-item');
        li.dataset.jobId = id;
        const input = document.createElement('div');
        input.className = 'input';
        const meta = document.createElement('div');
        meta.className = 'meta';
        const status = document.createElement('span');
        status.setAttribute('data-testid', 'job-status');
        const progress = document.createElement('span');
        progress.setAttribute('data-testid', 'job-progress');
        meta.append(status, progress);
        const result = document.createElement('div');
        result.className = 'result';
        result.setAttribute('data-testid', 'job-result');
        li.append(input, meta, result);
        return { li, input, status, progress, result };
      };

      const render = (job) => {
        let row = rows.get(job.id);
        if (!row) {
          row = makeRow(job.id);
          rows.set(job.id, row);
        }
        const setText = (el, text) => {
          if (el.textContent !== text) el.textContent = text;
        };
        setText(row.input, job.input);
        setText(row.status, job.status);
        setText(row.progress, `${job.progress.completed}/${job.progress.total}`);
        let resultText = '';
        if (job.status === 'completed' && job.result) resultText = job.result.output;
        else if (job.status === 'failed') resultText = job.error || '';
        setText(row.result, resultText);
        row.result.classList.toggle('failed', job.status === 'failed');
        return row.li;
      };

      const refresh = async () => {
        let data;
        try {
          const res = await fetch('/api/jobs');
          if (!res.ok) return;
          data = await res.json();
        } catch {
          return;
        }
        const jobs = Array.isArray(data.jobs) ? data.jobs : [];
        const seen = new Set();
        // Appending in order moves existing rows into place, so the list stays newest first.
        for (const job of jobs) {
          seen.add(job.id);
          listEl.appendChild(render(job));
        }
        for (const [id, row] of rows) {
          if (!seen.has(id)) {
            row.li.remove();
            rows.delete(id);
          }
        }
      };

      refresh();
      setInterval(refresh, 1000);
    })();
